insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b1media-grammar','Autor ___, że nowa aplikacja poprawi bezpieczeństwo.','["twierdzi","wynika","streszcza się"]',0,'Twierdzić вводит утверждение автора и сочетается с że.',0),
('b1media-grammar','Z raportu ___, że większość czytelników sprawdza datę.','["wynika","zaprzecza","relacjonuje"]',0,'Безличная конструкция z raportu wynika, że передаёт вывод из источника.',1),
('b1media-grammar','Reporter powiedział: «Mieszkańcy protestują». Reporter relacjonował, ___.','["że mieszkańcy protestują","czy mieszkańcy protestują","żeby mieszkańcy protestują"]',0,'В пересказе сообщения содержание вводится союзом że.',2),
('b1media-grammar','Najpierw podaj temat, ___ przedstaw główną myśl i szczegóły.','["następnie","ponieważ","mimo że"]',0,'Następnie связывает последовательные части пересказа.',3),
('b1media-grammar','Составьте: Автор подчёркивает, что заголовок не передаёт главную мысль.','["Autor podkreśla, że nagłówek nie oddaje głównej myśli.","Autor wynika, czy nagłówek nie oddaje główną myśl.","Autor podkreślać, żeby nagłówek nie oddaje."]',0,'После podkreśla содержание вводится że; oddawać требует родительного падежа.',4),
('b1media-grammar','Составьте: Сначала я проверил источник, а затем кратко пересказал публикацию.','["Najpierw sprawdziłem źródło, a następnie krótko streściłem publikację.","Ponieważ sprawdziłem źródło, następnie streszczam publikacją.","Najpierw źródło sprawdzałem, mimo że streścił publikację."]',0,'Najpierw… a następnie задаёт ясную структуру; streścić принимает винительный падеж.',5),
('b1media-quiz','Что означает wiarygodne źródło?','["источник, которому можно доверять","популярный комментарий","короткий заголовок"]',0,'Wiarygodne źródło содержит проверяемые сведения и прозрачное авторство.',0),
('b1media-quiz','Nie znam autora ani daty, więc nie będę ___ tej wiadomości.','["udostępniać","wynikać","nagłówkować"]',0,'Udostępniać wiadomość — делиться сообщением.',1),
('b1media-quiz','Który czasownik wprowadza zdecydowaną opinię autora?','["twierdzić","wynikać z","porównać"]',0,'Twierdzić показывает, что именно утверждает автор.',2),
('b1media-quiz','Z danych ___, że zainteresowanie wzrosło.','["wynika","podkreśla","udostępnia"]',0,'Форма wynika используется для вывода, основанного на данных.',3),
('b1media-quiz','Jak zacząć uporządkowane streszczenie?','["Tekst dotyczy…, a jego główna myśl to…","Wszystko w tekście jest ważne.","Nie pamiętam źródła, ale…"]',0,'Хороший пересказ называет тему и основную мысль.',4),
('b1media-quiz','Autor zaprzeczył, ___ opublikował nieprawdziwe dane.','["że","czy","więc"]',0,'После zaprzeczył содержание сообщения вводится że.',5),
('b1media-quiz','Co najlepiej pomaga sprawdzić wiadomość?','["Porównanie daty, autora i kilku źródeł","Przeczytanie tylko komentarzy","Udostępnienie samego nagłówka"]',0,'Сопоставление реквизитов и независимых источников снижает риск ошибки.',6),
('b1media-quiz','Выберите естественное сочетание.','["streścić publikację","wynikać komentarz","zaprzeczyć źródłem"]',0,'Streścić publikację — кратко передать содержание публикации.',7),
('b1media-quiz','Reporter ___ przebieg debaty, a ekspert wyjaśniał dane.','["relacjonował","wynikał","udostępniał się"]',0,'Relacjonować означает последовательно освещать событие.',8),
('b1media-quiz','Które zdanie oddziela fakt od opinii?','["Raport podaje liczbę, natomiast autor ocenia jej znaczenie.","Każdy popularny wpis jest prawdziwy.","Nagłówek zawsze wystarcza."]',0,'Первый вариант явно различает данные и авторскую оценку.',9),
('b1media-reading-check','Co zobaczyła Marta rano?','["Wpis o rzekomym zamknięciu biblioteki","Relację z koncertu","Reklamę nowej książki"]',0,'В ленте появился пост о якобы закрывающейся библиотеке.',0),
('b1media-reading-check','Dlaczego nagłówek wzbudził jej wątpliwości?','["Nie podawał autora ani daty decyzji","Był napisany po polsku","Zawierał nazwę dzielnicy"]',0,'В заголовке не было проверяемых реквизитов.',1),
('b1media-reading-check','Jak Marta sprawdziła informację?','["Porównała wpis z oficjalną stroną i lokalnym portalem","Zapytała tylko autora komentarza","Natychmiast udostępniła wpis"]',0,'Она обратилась к двум более прозрачным источникам.',2),
('b1media-reading-check','Co naprawdę planowała biblioteka?','["Krótki remont jednego piętra","Całkowite zamknięcie","Przeprowadzkę do innego miasta"]',0,'Речь шла лишь о ремонте одного этажа.',3),
('b1media-reading-check','Jak Marta streściła sytuację znajomym?','["Podała główną myśl, źródła i ważne szczegóły","Powtórzyła sam alarmujący nagłówek","Usunęła wszystkie informacje"]',0,'Её пересказ отделял подтверждённую суть от преувеличения.',4),
('b1media-reading-check','Jaki jest główny wniosek tekstu?','["Przed udostępnieniem trzeba sprawdzić kontekst i źródła","Najpopularniejszy wpis jest zawsze dokładny","Komentarze zastępują oficjalne informacje"]',0,'Главная мысль — осознанная проверка до распространения сообщения.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values
('b1media-wiadomosc-ktora-wymagala-sprawdzenia','b1-media-internet','Wiadomość, która wymagała sprawdzenia','Как проверить публикацию и передать её главную мысль','B1',8,'📰','["Rano Marta zobaczyła w mediach społecznościowych alarmujący wpis: biblioteka w jej dzielnicy miała zostać zamknięta. Nagłówek brzmiał poważnie, ale publikacja nie zawierała nazwiska autora ani daty decyzji. W komentarzach jedni mieszkańcy wyrażali złość, a inni od razu udostępniali wiadomość znajomym.","Marta postanowiła sprawdzić źródło informacji. Na oficjalnej stronie biblioteki znalazła komunikat o remoncie jednego piętra. Następnie porównała go z artykułem lokalnego portalu, który relacjonował posiedzenie rady dzielnicy i podawał dokładny termin prac.","Z obu źródeł wynikało, że biblioteka pozostanie otwarta, chociaż przez dwa tygodnie część sal będzie niedostępna. Dyrektorka podkreślała, że wszystkie zajęcia dla dzieci odbędą się zgodnie z planem. Zaprzeczyła też, że instytucji grozi całkowite zamknięcie.","Marta napisała znajomym krótkie streszczenie. Najpierw podała główną myśl, następnie wymieniła sprawdzone źródła, a na końcu wyjaśniła, skąd wzięło się nieporozumienie. Zrozumiała, że alarmujący nagłówek może wprowadzać w błąd, jeśli czytelnik nie sprawdzi daty, autora i szerszego kontekstu."]','{"alarmujący":{"lemma":"alarmujący","translation":"тревожный","part_of_speech":"прилагательное"},"miała zostać":{"lemma":"mieć zostać","translation":"должна была быть","part_of_speech":"глагольная конструкция"},"zawierała":{"lemma":"zawierać","translation":"содержать","part_of_speech":"глагол"},"wyrażali":{"lemma":"wyrażać","translation":"выражать","part_of_speech":"глагол"},"postanowiła":{"lemma":"postanowić","translation":"решить","part_of_speech":"глагол"},"komunikat":{"lemma":"komunikat","translation":"сообщение; объявление","part_of_speech":"существительное"},"remoncie":{"lemma":"remont","translation":"ремонт","part_of_speech":"существительное"},"posiedzenie":{"lemma":"posiedzenie","translation":"заседание","part_of_speech":"существительное"},"pozostanie":{"lemma":"pozostać","translation":"остаться","part_of_speech":"глагол"},"niedostępna":{"lemma":"niedostępny","translation":"недоступный","part_of_speech":"прилагательное"},"odbędą się":{"lemma":"odbyć się","translation":"состояться","part_of_speech":"глагол"},"grozi":{"lemma":"grozić","translation":"угрожать","part_of_speech":"глагол"},"streszczenie":{"lemma":"streszczenie","translation":"краткий пересказ","part_of_speech":"существительное"},"wymieniła":{"lemma":"wymienić","translation":"перечислить","part_of_speech":"глагол"},"nieporozumienie":{"lemma":"nieporozumienie","translation":"недоразумение","part_of_speech":"существительное"},"szerszego":{"lemma":"szeroki","translation":"более широкий","part_of_speech":"прилагательное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b1media-reading-check"}',30,true)
